public class RandomWikiPage {

    public static void main(String[] args) {
        try {
            // make a GET request to retrieve a random Wikipedia page
            URL url = new URL("https://en.wikipedia.org/w/api.php?action=query&list=random&rnnamespace=0&rnlimit=1&format=json");
            HttpURLConnection con = (HttpURLConnection) url.openConnection();
            con.setRequestMethod("GET");

            // read the API response into a string
            BufferedReader in = new BufferedReader(new InputStreamReader(con.getInputStream()));
            String response = "";
            String line;
            while ((line = in.readLine()) != null) {
                response += line;
            }
            in.close();

            // parse the response JSON to extract the title of the random page
            JSONObject json = new JSONObject(response);
            String randomTitle = json.getJSONObject("query").getJSONArray("random").getJSONObject(0).getString("title");

            // print the title of the random page
            System.out.println(randomTitle);

        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}
``` 

